@dataclass(frozen=True)
class OpenItem:
    subject: str
    reason: str
    required_confirmation: str
    sources: tuple[SourceReference, ...] = ()


@dataclass(frozen=True)
class ReceiptSummary:
    dine_in: Decimal
    offsite: Decimal
    total: Decimal
